        public HighSchoolCareerResult Start(StartHighSchoolCareerParams p)
        {
            var seed=Seed(p.Seed);var preset=PitcherPresetCatalog.All.FirstOrDefault(x=>x.Id==p.PresetId);if(preset==null)throw Invalid("unknown career pitcher preset");if(p.CreationAllocation.Total!=5||p.InheritedMemories.Count>4||p.Karmas.Distinct().Count()!=p.Karmas.Count||p.Karmas.Count>2||string.IsNullOrWhiteSpace(p.Identity.Name)||string.IsNullOrWhiteSpace(p.Identity.Region))throw Invalid("career creation or inherited memories are invalid");
            var careerId="career-"+p.Seed+"-life-"+p.LifeNumber;var talent=TalentRules.Make(careerId);var boosts=new HashSet<SoulBoostId>(p.SoulBoosts??new SoulBoostId[0]);if(boosts.Contains(SoulBoostId.TalentBreak))talent=RaiseLowest(talent);
            var wind=CareerWind.For(careerId,CareerRulesVersion.V2);var pitcher=ApplyCreation(preset.Pitcher,p.CreationAllocation,p.Identity);pitcher=ApplyInheritance(pitcher,p.InheritedSoulTotal??p.InheritedSoulPoints,p.InheritedSoulDomain,p.InheritedMemories,talent,p.InheritanceRulesVersion,boosts.Contains(SoulBoostId.HeadStart)?5:0);pitcher=ApplyKarmas(pitcher,p.Karmas);pitcher=CareerSignatureLegacy.Apply(p.SignatureLegacyId,pitcher);
            var reward=1000+p.Karmas.Sum(x=>x.RewardPermille())+wind.RewardBonusPermille;var state=new HighSchoolCareerSnapshot {CareerId=careerId,Revision=0,LifeNumber=p.LifeNumber,Phase=HighSchoolCareerPhase.Prologue,Identity=p.Identity,Difficulty=p.Difficulty,Karmas=p.Karmas.ToArray(),LegacyRewardPermille=reward,MemorySlots=(p.Karmas.Contains(KarmaId.ErasedMemory)?2:3)+(boosts.Contains(SoulBoostId.ExtraMemory)?1:0),Pitcher=pitcher,SchoolOptions=Schools(p.Identity.Region),School=null,Rival=MakeRival(seed,p.Difficulty.SimulationDifficulty,p.Karmas,wind.RivalBonus),Chapter=Chapters[0],ChapterTrainingCount=0,TotalTrainingsCompleted=0,MilestoneIndex=0,RelationshipsCompleted=0,RelationshipTrust=50,ManagerTrust=50,CatcherTrust=50,RivalTrust=50,SelectedAwakenings=new AwakeningId[0],AwakeningOptions=new AwakeningId[0],Fatigue=5,Performance=new CareerPerformanceSnapshot(),SeasonLog=new ProGameLine[0],News=((wind.NewsLine==null?new string[0]:new[]{wind.NewsLine}).Concat(PrologueNews(p.Identity,p.LifeNumber,p.InheritedMemories.Count))).ToArray(),FanInterest=wind.StartingFanInterest,LegacyOptions=new MemoryCardId[0],SelectedMemories=new MemoryCardId[0],BalanceVersion=PitcherPresetCatalog.BalanceVersion,WorldRulesVersion=2,ArmRisk=0,InjuryRecovery=0,Schedule=MakeSchedule(careerId),Talent=talent,SoulBoosts=boosts.Count==0?null:boosts.Select(x=>x.ToString()).OrderBy(x=>x).ToArray(),AwakeningSparks=null};
            Sign(state);return Result(seed,state,"high_school_career_started");
        }
