        public TrainingGrowthOutlook TrainingOutlook(HighSchoolCareerSnapshot state,TrainingFocus focus,TrainingIntensity intensity){if((state.InjuryRecovery??0)>0)return TrainingGrowthOutlook.None;var ability=TalentRules.From(focus);var talent=state.Talent??TalentSnapshot.Unlimited;if(Rating(focus,state.Pitcher)>=talent.Grade(ability).Ceiling())return TrainingGrowthOutlook.Wall;var value=TrainingSignalBase(state,focus,intensity,state.TrainingOpportunity!=null&&state.TrainingOpportunity.Focus==focus);var bonus=state.CareerWind.Rules.TrainingGrowthBonus(focus);var lo=TrainingGrowth(Math.Max(60,value-45))+bonus;var hi=TrainingGrowth(Math.Max(60,value+45))+bonus;if(lo>=2)return TrainingGrowthOutlook.Two;if(lo==1&&hi>=2)return TrainingGrowthOutlook.OneOrTwo;if(lo==1)return TrainingGrowthOutlook.One;if(hi==0)return TrainingGrowthOutlook.None;return TrainingGrowthOutlook.ZeroOrOne;}
        public HighSchoolCareerResult CommitTraining(CommitCareerTrainingParams p)
        {
            var seed=Validate(p.Seed,p.State,HighSchoolCareerPhase.Training);var schedule=p.State.Schedule??CareerScheduleSnapshot.FixedDefault;var required=schedule.TrainingsByChapter[p.State.Chapter.Number-1];if(p.State.School==null||p.State.ChapterTrainingCount>=required)throw Invalid("career training is out of order");var number=p.State.TotalTrainingsCompleted+1;var rehab=(p.State.InjuryRecovery??0)>0;var focus=rehab?TrainingFocus.Recovery:p.Focus;var wind=p.State.CareerWind.Rules;var rng=new SplitMix64(seed^(ulong)number^0x434152454552UL);var hit=!rehab&&p.State.TrainingOpportunity!=null&&p.Focus==p.State.TrainingOpportunity.Focus;var signal=Math.Max(60,TrainingSignalBase(p.State,p.Focus,p.Intensity,hit)+rng.NextInt(91)-45);var jackpotChance=p.State.SoulBoosts!=null&&p.State.SoulBoosts.Contains(SoulBoostId.TrainingRhythm.ToString())?26:16;var jackpot=!rehab&&focus!=TrainingFocus.Recovery&&rng.NextInt(100)<jackpotChance;var baseGrowth=rehab||focus==TrainingFocus.Recovery?0:TrainingGrowth(signal);if(baseGrowth==0&&number==1&&p.State.LifeNumber==1&&!rehab&&focus!=TrainingFocus.Recovery)baseGrowth=1;var raw=(jackpot?baseGrowth*2:baseGrowth)+(rehab?0:wind.TrainingGrowthBonus(focus));var before=Rating(focus,p.State.Pitcher);var talent=p.State.Talent??TalentSnapshot.Unlimited;var application=raw>0?TalentRules.Apply(talent,TalentRules.From(p.Focus),Rating(p.Focus,p.State.Pitcher),raw):new TalentApplication(0,talent,null);var target=focus==TrainingFocus.BreakingBall&&((p.State.BalanceVersion??1)>=4)?PitcherGrowthRules.NormalizeBreakingBallTarget(p.TargetPitch,p.State.Pitcher):null;var pitcher=Grow(p.State.Pitcher,p.Focus,application.Allowed,p.State.BalanceVersion,target);var baseFatigue=p.Intensity==TrainingIntensity.Light?3:p.Intensity==TrainingIntensity.Standard?8:15;var fatigue=rehab?Clamp(p.State.Fatigue+wind.TrainingFatigueModifier(TrainingFocus.Recovery)-wind.AdjustedRecovery(24),0,100):Clamp(p.State.Fatigue+baseFatigue+wind.TrainingFatigueModifier(focus)-(p.Focus==TrainingFocus.Recovery?wind.AdjustedRecovery(18):0),0,100);var after=Rating(focus,pitcher);var growth=after-before;var feedback=rehab?"재활 훈련으로 팔 상태를 회복합니다. 이번 훈련은 성장 없이 지나갑니다.":growth>0?(Label(focus)+" 능력치가 "+growth+" 올랐습니다."):"이번 훈련에서는 능력치가 오르지 않았습니다. 피로와 훈련 강도를 조절해 다시 시도할 수 있습니다.";if(jackpot&&growth>0)feedback="대성공! 오늘은 몸이 완전히 열렸습니다. "+feedback;
            var s=Next(p.State);s.Pitcher=pitcher;s.Fatigue=fatigue;s.TotalTrainingsCompleted=number;s.ChapterTrainingCount++;s.LastTraining=new CareerTrainingSnapshot(number,focus,p.Intensity,growth,fatigue-p.State.Fatigue,feedback,before,after,p.State.Fatigue,fatigue,hit,application.Bloomed,application.Bloomed.HasValue?(TalentGrade?)application.Talent.Grade(application.Bloomed.Value):null,jackpot&&growth>0,target);s.Talent=application.Talent;s.InjuryRecovery=rehab?(p.State.InjuryRecovery??0)-1:p.State.InjuryRecovery;s.ArmRisk=rehab?Math.Max(0,(p.State.ArmRisk??0)-10):Clamp((p.State.ArmRisk??0)+(((p.State.BalanceVersion??1)>=4)?TrainingArmRisk(focus,p.Intensity):0),0,100);if(application.Bloomed.HasValue)s.AwakeningSparks=Math.Min(6,(s.AwakeningSparks??0)+1);if(s.ChapterTrainingCount>=required)EnterMilestone(s,seed,0);else{s.Phase=HighSchoolCareerPhase.Training;s.TrainingOpportunity=TrainingOpportunity(s.CareerId,s.TotalTrainingsCompleted,s.Fatigue,s.InjuryRecovery??0);}return Finish(seed,s,rehab?"career_training_rehab":"career_training_completed",new[]{"training."+focus.Value()});
        }

        public HighSchoolTrainingBlockResult CommitTrainingBlock(CommitCareerTrainingBlockParams p)
        {
            if(p==null)throw new ArgumentNullException(nameof(p));
            if(p.MaximumSessions<2||p.MaximumSessions>3)throw Invalid("training block requires two or three sessions");
            Validate(p.Seed,p.State,HighSchoolCareerPhase.Training);
            var startingPitcher=p.State.Pitcher;
            var startingFatigue=p.State.Fatigue;
            var result=(HighSchoolCareerResult)null;
            var seed=p.Seed;
            var state=p.State;
            var completed=0;
            var stop=TrainingBlockStopReason.MaximumSessions;
            var sessions=new List<CareerTrainingSnapshot>();
            while(completed<p.MaximumSessions&&state.Phase==HighSchoolCareerPhase.Training)
            {
                result=CommitTraining(new CommitCareerTrainingParams(seed,state,p.Focus,p.Intensity,p.TargetPitch));
                completed++;
                seed=result.NextSeed;
                state=result.Snapshot;
                sessions.Add(state.LastTraining);
                var reason=TrainingBlockStop(state,p.Focus);
                if(reason.HasValue){stop=reason.Value;break;}
            }
            if(result==null)throw Invalid("training block did not complete a session");
            var growth=RatingTotal(state.Pitcher)-RatingTotal(startingPitcher);
            var block=new CareerTrainingBlockSnapshot(p.MaximumSessions,completed,p.Focus,p.Intensity,
                state.LastTraining==null?null:state.LastTraining.TargetPitch,stop,growth,state.Fatigue-startingFatigue,sessions);
            return new HighSchoolTrainingBlockResult(result,block);
        }

        public HighSchoolCareerResult ResolveRelationship(ResolveCareerRelationshipParams p)
        {
            var seed=Validate(p.Seed,p.State,HighSchoolCareerPhase.Relationship);if(p.State.CurrentRelationshipEvent!=null&&p.State.CurrentRelationshipEvent.Id==ArmCareEventId)return ResolveArmCare(seed,p.State,p.Response);var category=p.State.CurrentRelationshipEvent==null?"coach":p.State.CurrentRelationshipEvent.Category;var target=RelationshipTargetForEventCategory(category);var impact=RelationshipImpact(category,p.Response);var change=p.State.CareerWind.Rules.AdjustedRelationshipTrustChange(impact.Trust,target);if(p.State.Karmas.Contains(KarmaId.StubbornCoach)&&target==RelationshipTarget.Coach)change=change<0?change*2:change/2;var manager=p.State.ManagerTrust??p.State.RelationshipTrust;var catcher=p.State.CatcherTrust??p.State.RelationshipTrust;var rival=p.State.RivalTrust??p.State.RelationshipTrust;var before=target==RelationshipTarget.Coach?manager:target==RelationshipTarget.Catcher?catcher:rival;if(target==RelationshipTarget.Coach)manager=Clamp(manager+change,0,100);else if(target==RelationshipTarget.Catcher)catcher=Clamp(catcher+change,0,100);else rival=Clamp(rival+change,0,100);var fatigue=Clamp(p.State.Fatigue+impact.Fatigue,0,100);var fans=Clamp(p.State.FanInterest+p.State.CareerWind.Rules.AdjustedFanInterestChange(impact.Fans),0,100);var pitcher=p.State.Pitcher;var abilityBefore=impact.Focus.HasValue?(int?)Rating(impact.Focus.Value,pitcher):null;if(impact.Focus.HasValue)pitcher=Grow(pitcher,impact.Focus.Value,1);var abilityAfter=impact.Focus.HasValue?(int?)Rating(impact.Focus.Value,pitcher):null;var s=Next(p.State);s.Pitcher=pitcher;s.RelationshipsCompleted++;s.ManagerTrust=manager;s.CatcherTrust=catcher;s.RivalTrust=rival;s.RelationshipTrust=(manager+catcher+rival)/3;s.Fatigue=fatigue;s.FanInterest=fans;s.LastRelationship=new CareerRelationshipResultSnapshot(s.RelationshipsCompleted,target==RelationshipTarget.Coach?"coach":target==RelationshipTarget.Catcher?"catcher":"rival",p.State.CurrentRelationshipEvent==null?"대화":p.State.CurrentRelationshipEvent.Title,p.Response,before,target==RelationshipTarget.Coach?manager:target==RelationshipTarget.Catcher?catcher:rival,p.State.Fatigue,fatigue,p.State.FanInterest,fans,impact.Focus,abilityBefore,abilityAfter,impact.Text);s.News=(new[]{(p.State.CurrentRelationshipEvent==null?"대화":p.State.CurrentRelationshipEvent.Title)+" — "+impact.Text}).Concat(s.News).ToArray();AdvanceMilestone(s,seed);return Finish(seed,s,"career_relationship_resolved",new[]{"relationship."+p.Response.ToString().ToLowerInvariant()});
