        public HighSchoolCareerResult RecordImportantGame(RecordCareerGameParams p)
        {
            var seed=Validate(p.Seed,p.State,HighSchoolCareerPhase.ImportantGame);var expected=p.State.Performance.ImportantGamesCompleted+1;if(p.Report.ScenarioNumber!=expected||p.Report.Pitches<=0||p.Report.RecommendationAccepted<0||p.Report.RecommendationAccepted>p.Report.Pitches)throw Invalid("career important game report is invalid");var growth=CareerGameGrowth.Evaluate(p.State,p.Report);var performance=p.State.Performance.Adding(p.Report);var fans=Clamp(p.State.FanInterest+p.State.CareerWind.Rules.AdjustedFanInterestChange(Math.Max(2,p.Report.Strikeouts*2-p.Report.RunsAllowed*2)),0,100);var risk=Clamp((p.State.ArmRisk??0)+(p.Report.Pitches>ArmPitchFloor?p.Report.Pitches-ArmPitchFloor+Math.Max(0,p.State.Fatigue-ArmFatigueFloor):0),0,100);var spark=Math.Min(6,(p.State.AwakeningSparks??0)+(p.Report.RunsAllowed==0||p.Report.Strikeouts>=4?2:0)+(p.Report.ActualDamage<=p.Report.ExpectedDamage?1:0)+(growth!=null&&growth.BloomedAbility.HasValue?1:0));var rng=new SplitMix64(seed^0x4853504C4159UL);var outs=p.Report.Outs??Math.Min(27,p.Report.Pitches/5);var support=p.Report.TeamRuns??LeagueBaseline.HighSchoolTeamRuns(ref rng);var opponent=p.Report.RunsAllowed+LeagueBaseline.RestOfHighSchoolTeamRuns(Math.Max(0,27-outs),ref rng);var line=new ProGameLine(p.State.Chapter.SchoolYear,p.State.Chapter.Number,(p.State.SeasonLog==null?0:p.State.SeasonLog.Count)+1,false,outs,p.Report.Strikeouts,p.Report.Walks,p.Report.RunsAllowed,p.Report.Pitches,support,opponent,DecisionRules.Decide(false,false,outs,p.Report.RunsAllowed,support,opponent),true,p.Report.Hits,p.Report.HomeRuns);
            var s=Next(p.State);s.Pitcher=growth==null?p.State.Pitcher:growth.Applying(p.State.Pitcher);s.Talent=growth==null?p.State.Talent:growth.ResultingTalent;s.Performance=performance;s.FanInterest=fans;s.ArmRisk=risk;s.AwakeningSparks=spark;s.Fatigue=Clamp(p.State.Fatigue+Math.Max(5,p.Report.Pitches*Math.Max(60,140-p.State.Pitcher.Stamina)/200),0,100);s.SeasonLog=(p.State.SeasonLog??new ProGameLine[0]).Concat(new[]{line}).ToArray();s.News=(new[]{p.Report.RunsAllowed==0?s.Pitcher.Name+", "+s.Rival.Name+"과의 승부에서 무실점":s.Pitcher.Name+", "+p.Report.Strikeouts+"탈삼진 · "+p.Report.Walks+"볼넷 · "+p.Report.RunsAllowed+"실점"}).Concat(s.News).ToArray();AdvanceMilestone(s,seed);return Finish(seed,s,"career_important_game_completed",new[]{"important_game."+expected}.Concat(growth==null?new string[0]:new[]{growth.ReasonCode}).ToArray());
