        public HighSchoolCareerResult ChooseAwakening(ChooseCareerAwakeningParams p){var seed=Validate(p.Seed,p.State,HighSchoolCareerPhase.Awakening);if(!p.State.AwakeningOptions.Contains(p.Awakening)||p.State.SelectedAwakenings.Contains(p.Awakening))throw Invalid("career awakening is not available");var s=Next(p.State);s.Pitcher=ApplyAwakening(p.State.Pitcher,p.Awakening);s.SelectedAwakenings=p.State.SelectedAwakenings.Concat(new[]{p.Awakening}).ToArray();s.AwakeningOptions=new AwakeningId[0];s.AwakeningSparks=0;s.News=(new[]{"‘"+AwakeningTitle(p.Awakening)+"’을 익혔습니다."}).Concat(s.News).ToArray();AdvanceMilestone(s,seed);return Finish(seed,s,"career_awakening_selected",new[]{"awakening."+p.Awakening.Value()});}
        public HighSchoolCareerResult AdvanceChapter(AdvanceCareerChapterParams p){var seed=Validate(p.Seed,p.State,HighSchoolCareerPhase.ChapterReview);if(p.State.Chapter.Number>=8)throw Invalid("final chapter cannot advance");var games=SimulateChapterGames(p.State,p.State.Chapter,seed);var s=Next(p.State);s.Phase=HighSchoolCareerPhase.Training;s.Chapter=Chapters[p.State.Chapter.Number];s.ChapterTrainingCount=0;s.MilestoneIndex=0;s.SeasonLog=(p.State.SeasonLog??new ProGameLine[0]).Concat(games).ToArray();s.TrainingOpportunity=TrainingOpportunity(s.CareerId,s.TotalTrainingsCompleted,s.Fatigue,s.InjuryRecovery??0);s.News=(new[]{ChapterGameHeadline(games),s.Chapter.Title+" — "+s.Chapter.Theme+"."}).Concat(s.News).ToArray();return Finish(seed,s,"career_chapter_advanced",new[]{"chapter."+s.Chapter.Number});}

        public static DraftEvaluationComponents DraftEvaluationCore(HighSchoolCareerSnapshot s){var v4=(s.BalanceVersion??1)>=4;var ratings=s.Pitcher.Stuff+s.Pitcher.Command+s.Pitcher.Movement+s.Pitcher.Stamina;var quality=v4?s.Performance.Strikeouts*4-s.Performance.Walks*2-s.Performance.RunsAllowed*2:s.Performance.Strikeouts*3-s.Performance.Walks*2-s.Performance.RunsAllowed*3;var process=Clamp((s.Performance.ExpectedDamage-s.Performance.ActualDamage)/350,-8,10);var auto=(s.SeasonLog??new ProGameLine[0]).Where(x=>!x.Played).ToArray();var outs=auto.Sum(x=>x.Outs);var runs=auto.Sum(x=>x.RunsAllowed);var cap=v4?2:4;var season=outs==0?0:Clamp((HighSchoolBaseline(s.LifeNumber,s.Pitcher.Id,s.BalanceVersion)-runs*27000/outs)*(v4?1:4)/1000,-cap,cap);var risk=s.ArmRisk??0;return new DraftEvaluationComponents(ratings/4+15,quality/(v4?6:4),process,s.SelectedAwakenings.Count,(s.RelationshipTrust-50)/10,season,(s.Karmas.Contains(KarmaId.UnknownLand)?3:0)+(s.Karmas.Contains(KarmaId.NoLastChance)?2:0),risk>=ArmWarningThreshold?4:risk>=45?2:0,Clamp((s.FanInterest-40)/15,-3,3),s.CareerWind.Rules.DraftEvaluationDelta);}
        public static int DraftThreshold(HighSchoolCareerSnapshot s)=>(s.Difficulty.CareerHarshness==DifficultyLevel.Relaxed?57:s.Difficulty.CareerHarshness==DifficultyLevel.Challenging?65:61)+((s.BalanceVersion??1)>=4?5:0);
        public static int DraftVariance(int? balanceVersion,int roll){if((balanceVersion??1)>=4){if(roll<0||roll>=5)throw new ArgumentOutOfRangeException(nameof(roll));return roll==0?-1:roll==4?1:0;}if(roll<0||roll>=11)throw new ArgumentOutOfRangeException(nameof(roll));return roll-5;}
        public static DraftForecastSnapshot DraftForecast(HighSchoolCareerSnapshot s){var score=Clamp(DraftEvaluationCore(s).Total,20,95);var threshold=DraftThreshold(s);var band=score>=78?"1라운드 예상":score>=70?"2~3라운드 예상":score>=threshold+5?"4~6라운드 예상":score>=threshold-5?"당락 경계 — 남은 경기가 정한다":"미지명권 — 아직 명단 밖";return new DraftForecastSnapshot(score,threshold,band,BestTeam(s.Pitcher).Name);}
        public HighSchoolCareerResult ResolveDraft(ResolveDraftParams p){var seed=Validate(p.Seed,p.State,HighSchoolCareerPhase.Draft);var rng=new SplitMix64(seed^0x445241465400UL);var score=Clamp(DraftEvaluationCore(p.State).Total+DraftVariance(p.State.BalanceVersion,rng.NextInt((p.State.BalanceVersion??1)>=4?5:11)),20,95);var drafted=score>=DraftThreshold(p.State);var team=drafted?BestTeam(p.State.Pitcher):null;int? round=drafted?(score>=78?1:score>=70?2:4):(int?)null;int? pick=round.HasValue?(round.Value-1)*10+rng.NextInt(10)+1:(int?)null;var draft=new DraftResultSnapshot(drafted?DraftOutcome.Drafted:DraftOutcome.Undrafted,score,drafted?(score>=78?"1라운드":score>=70?"2~3라운드":"4~6라운드"):"미지명",team,round,pick,round.HasValue?Math.Max(40000000,300000000-round.Value*45000000):(int?)null,team==null?null:"퓨처스 선발 10경기와 볼넷률 8% 이하",new[]{"능력 "+DraftEvaluationCore(p.State).RatingScore,"고교 공식 경기 "+DraftEvaluationCore(p.State).PerformanceScore},drafted?"지명 구단 · "+team.Name+". 구위와 고교 경기 기록에서 높은 평가를 받았습니다.":"마지막 라운드까지 이름이 불리지 않았습니다. 다음 선수에게 남길 기록을 고르세요.");var s=Next(p.State);s.Phase=drafted?HighSchoolCareerPhase.Completed:HighSchoolCareerPhase.Legacy;s.DraftResult=draft;s.LegacyOptions=MemoryOptions(p.State,seed);s.News=(new[]{drafted?"드래프트 지명 · "+team.Name+" · "+s.Pitcher.Name:"드래프트가 끝날 때까지 이름이 불리지 않았습니다."}).Concat(s.News).ToArray();return Finish(seed,s,"career_draft_resolved",new[]{"draft."+(drafted?"drafted":"undrafted")});}
        public HighSchoolCareerResult OpenLegacy(AdvanceCareerChapterParams p){var seed=Validate(p.Seed,p.State,HighSchoolCareerPhase.Completed);if(p.State.DraftResult==null||p.State.DraftResult.Outcome!=DraftOutcome.Drafted)throw Invalid("미지명 선수는 이미 유산을 고르는 단계입니다.");var s=Next(p.State);s.Phase=HighSchoolCareerPhase.Legacy;return Finish(seed,s,"career_legacy_opened",new[]{"legacy.opened"});}
        public HighSchoolCareerResult SelectLegacy(SelectCareerLegacyParams p){var seed=Validate(p.Seed,p.State,HighSchoolCareerPhase.Legacy);var s=Next(p.State);if(p.SignatureLegacyId.HasValue){if(p.MemoryCards.Count!=0)throw Invalid("signature legacy cannot be mixed with career memories");s.SelectedMemories=new MemoryCardId[0];}else{var unique=p.MemoryCards.Distinct().ToArray();if(unique.Length!=p.State.MemorySlots||unique.Any(x=>!p.State.LegacyOptions.Contains(x)))throw Invalid("select the available number of offered career memories");s.SelectedMemories=unique;s.LegacyOptions=unique;}s.Phase=HighSchoolCareerPhase.Completed;return Finish(seed,s,"career_legacy_selected");}

        public static CareerScheduleSnapshot MakeSchedule(string careerId){var rng=new SplitMix64(StableHash.Fnv1A64Value("run_skeleton|"+careerId));var total=12+rng.NextInt(5);var relationships=4+rng.NextInt(3);var games=4+rng.NextInt(3);var trainings=Enumerable.Repeat(1,8).ToArray();var remaining=total-8;while(remaining>0){var candidates=Enumerable.Range(0,8).Where(i=>trainings[i]<3).ToArray();trainings[candidates[rng.NextInt(candidates.Length)]]++;remaining--;}var queues=new List<Tuple<HighSchoolCareerPhase,int>>{Tuple.Create(HighSchoolCareerPhase.Relationship,relationships),Tuple.Create(HighSchoolCareerPhase.ImportantGame,games-1),Tuple.Create(HighSchoolCareerPhase.Awakening,2)};for(var i=queues.Count-1;i>0;i--){var j=rng.NextInt(i+1);var q=queues[i];queues[i]=queues[j];queues[j]=q;}var seq=new List<HighSchoolCareerPhase>();while(queues.Any(x=>x.Item2>0)){for(var i=0;i<queues.Count;i++)if(queues[i].Item2>0){seq.Add(queues[i].Item1);queues[i]=Tuple.Create(queues[i].Item1,queues[i].Item2-1);}}var milestones=Enumerable.Range(0,8).Select(i=>(IReadOnlyList<HighSchoolCareerPhase>)new List<HighSchoolCareerPhase>()).ToArray();var counts=Enumerable.Repeat(seq.Count/7,7).ToArray();var offset=rng.NextInt(7);for(var i=0;i<seq.Count%7;i++)counts[(offset+i)%7]++;var cursor=0;for(var chapter=0;chapter<7;chapter++)for(var i=0;i<counts[chapter]&&cursor<seq.Count;i++)((List<HighSchoolCareerPhase>)milestones[chapter]).Add(seq[cursor++]);milestones[7]=new[]{HighSchoolCareerPhase.Awakening,HighSchoolCareerPhase.ImportantGame};return new CareerScheduleSnapshot(trainings,milestones);}
        public static ArmHealthState ArmHealthStateFor(int? risk,int? recovery){if((recovery??0)>0)return ArmHealthState.Recovering;if((risk??0)>=ArmWarningThreshold)return ArmHealthState.Warning;if((risk??0)>=ArmCautionThreshold)return ArmHealthState.Caution;return ArmHealthState.Normal;}
        public static TrainingOpportunitySnapshot TrainingOpportunity(string careerId,int index,int fatigue=100,int injuryRecovery=0){var seed=StableHash.Fnv1A64Value(careerId+"|opportunity|"+index);var pick=(int)(seed%(ulong)Focuses.Length);var earned=fatigue>=45||injuryRecovery>0;Func<int,int> skip=start=>{var x=start;var steps=0;while(!earned&&Focuses[x]==TrainingFocus.Recovery&&steps<Focuses.Length){x=(x+1)%Focuses.Length;steps++;}return x;};pick=skip(pick);if(index>0){var prior=skip((int)(StableHash.Fnv1A64Value(careerId+"|opportunity|"+(index-1))%(ulong)Focuses.Length));if(pick==prior)pick=skip((pick+1)%Focuses.Length);}var focus=Focuses[pick];return new TrainingOpportunitySnapshot(focus,OpportunityReason(focus));}
        public static RelationshipTarget RelationshipTargetForEventCategory(string category){if(category=="coach")return RelationshipTarget.Coach;if(category=="rival")return RelationshipTarget.Rival;if(category=="catcher"||category=="growth"||category=="game"||category=="awakening"||category=="fan")return RelationshipTarget.Catcher;return RelationshipTarget.Coach;}
        public static int InheritancePointCap(int points,SoulInheritanceRulesVersion version=SoulInheritanceRulesVersion.V1)=>version==SoulInheritanceRulesVersion.V1?Math.Min(20,8+Math.Max(0,points)/60):Math.Min(20,Math.Max(1,(Math.Max(0,points)-20)/4));
        public static int AppliedInheritance(int points,SoulInheritanceRulesVersion version=SoulInheritanceRulesVersion.V1)=>Math.Min(Math.Max(0,points),InheritancePointCap(points,version));
        public static Tuple<int,int> NextInheritanceStep(int points,SoulInheritanceRulesVersion version){var current=AppliedInheritance(points,version);if(current>=20)return null;for(var p=Math.Max(0,points)+1;p<=Math.Max(0,points)+4000;p++){var applied=AppliedInheritance(p,version);if(applied>current)return Tuple.Create(p,applied);}return null;}

        private void EnterMilestone(HighSchoolCareerSnapshot s,ulong seed,int index){s.MilestoneIndex=index;var phases=s.Schedule.MilestonesByChapter[s.Chapter.Number-1];var phase=index<phases.Count?phases[index]:(s.Chapter.Number==8?HighSchoolCareerPhase.Draft:HighSchoolCareerPhase.ChapterReview);s.Phase=phase;s.AwakeningOptions=phase==HighSchoolCareerPhase.Awakening?AwakeningTree.Available(s.SelectedAwakenings,s.AwakeningSparks):new AwakeningId[0];s.CurrentGameScenario=phase==HighSchoolCareerPhase.ImportantGame?GameScenario(s,seed):null;s.CurrentRelationshipEvent=phase==HighSchoolCareerPhase.Relationship?RelationshipEvent(s,seed):null;}
        private void AdvanceMilestone(HighSchoolCareerSnapshot s,ulong seed){EnterMilestone(s,seed,s.MilestoneIndex+1);}
        private CareerEventContent RelationshipEvent(HighSchoolCareerSnapshot s,ulong seed){if(s.RelationshipsCompleted>=3&&ArmHealthStateFor(s.ArmRisk,s.InjuryRecovery)==ArmHealthState.Warning)return new CareerEventContent(ArmCareEventId,"팔 상태 경고","health","최근 등판 뒤 팔이 평소보다 무겁습니다. 트레이너가 오늘 어떻게 할지 묻습니다.");var core=new[]{"coach","catcher","rival"};if(s.RelationshipsCompleted<3){var rng=new SplitMix64(StableHash.Fnv1A64Value("core_order|"+s.CareerId));for(var i=2;i>0;i--){var j=rng.NextInt(i+1);var t=core[i];core[i]=core[j];core[j]=t;}var pool=HighSchoolContentCatalog.Events.Where(x=>x.Category==core[s.RelationshipsCompleted]).ToArray();return pool[(int)(seed%(ulong)pool.Length)];}if(s.LifeNumber>1){var rr=new SplitMix64(StableHash.Fnv1A64Value("rebirth_event|"+s.CareerId+"|"+s.RelationshipsCompleted));if(rr.NextInt(3)==0)return HighSchoolContentCatalog.RebirthEvents[rr.NextInt(HighSchoolContentCatalog.RebirthEvents.Count)];}var extended=HighSchoolContentCatalog.Events.Where(x=>x.Category!="coach"&&x.Category!="catcher"&&x.Category!="rival").ToArray();return extended[(int)(StableHash.Fnv1A64Value("relationship_pool|"+s.CareerId+"|"+s.RelationshipsCompleted)%(ulong)extended.Length)];}
        private ImportantGameScenarioContent GameScenario(HighSchoolCareerSnapshot s,ulong seed){if(s.Chapter.Number==8)return HighSchoolContentCatalog.Scenarios.First(x=>x.Id=="game-one-run");if(s.Chapter.Number==4)return HighSchoolContentCatalog.Scenarios.First(x=>x.Id=="game-national-final");var pool=HighSchoolContentCatalog.Scenarios.Where(x=>x.MinChapter<=1).ToArray();var run=StableHash.Fnv1A64Value("game_scenario|"+s.CareerId);return pool[((int)(run%(ulong)pool.Length)+s.Performance.ImportantGamesCompleted*7)%pool.Length];}
        private HighSchoolCareerResult ResolveArmCare(ulong seed,HighSchoolCareerSnapshot state,RelationshipResponse response){var s=Next(state);var risk=state.ArmRisk??0;if(response==RelationshipResponse.Challenge){risk=Clamp(risk+ArmPushThroughRisk,0,100);s.Fatigue=Clamp(s.Fatigue+4,0,100);if(risk>=ArmInjuryThreshold){s.InjuryRecovery=risk>=92?2:1;risk=50;if(s.Karmas.Contains(KarmaId.NoLastChance))s.Phase=HighSchoolCareerPhase.Draft;}}else if(response==RelationshipResponse.Listen){risk=Math.Max(0,risk-ArmRestRelief);s.Fatigue=Clamp(s.Fatigue-30,0,100);}else{risk=0;s.Fatigue=Clamp(s.Fatigue-ArmExamRelief,0,100);}s.ArmRisk=risk;s.RelationshipsCompleted++;if(s.Phase!=HighSchoolCareerPhase.Draft)AdvanceMilestone(s,seed);return Finish(seed,s,s.InjuryRecovery>0?"career_arm_injury":"career_arm_care");}
        private static IReadOnlyList<ProGameLine> SimulateChapterGames(HighSchoolCareerSnapshot s,CareerChapterSnapshot chapter,ulong seed){var rng=new SplitMix64(seed^0x485347414D45UL);var rows=new List<ProGameLine>();for(var i=0;i<2;i++){var outs=15+rng.NextInt(7);var strikeouts=Math.Max(0,(s.Pitcher.Stuff+s.Pitcher.Movement-55)/12+rng.NextInt(5));var walks=Math.Max(0,4-s.Pitcher.Command/20+rng.NextInt(3));var runs=Math.Max(0,5-(s.Pitcher.Command+s.Pitcher.Movement)/30+rng.NextInt(4)+DifficultyScale.HighSchool(chapter.Number,s.LifeNumber)/2);var support=LeagueBaseline.HighSchoolTeamRuns(ref rng);var opponent=runs+LeagueBaseline.RestOfHighSchoolTeamRuns(27-outs,ref rng);rows.Add(new ProGameLine(chapter.SchoolYear,chapter.Number,(s.SeasonLog==null?0:s.SeasonLog.Count)+i+1,true,outs,strikeouts,walks,runs,outs*5+walks*3,support,opponent,DecisionRules.Decide(true,false,outs,runs,support,opponent),false,Math.Max(0,runs*2+rng.NextInt(5)),0));}return rows;}
        private static string ChapterGameHeadline(IReadOnlyList<ProGameLine> games){var wins=games.Count(x=>x.Decision==PitchingDecision.Win);return "팀 경기 "+games.Count+"차례 등판 · "+games.Sum(x=>x.Outs)/3+"이닝 "+games.Sum(x=>x.Strikeouts)+"탈삼진 "+games.Sum(x=>x.RunsAllowed)+"실점"+(wins>0?" · "+wins+"승":"");}
        private static int HighSchoolBaseline(int life,string id,int? version){var baseline=(version??1)>=4?(id=="pitcher-command"?1900:id=="pitcher-artist"?2700:id=="pitcher-stamina"?2900:4930):2530;var scale=Enumerable.Range(1,8).Sum(ch=>DifficultyScale.HighSchool(ch,life))*100/8;var first=Enumerable.Range(1,8).Sum(ch=>DifficultyScale.HighSchool(ch,1))*100/8;return baseline+432*(scale-first)/100;}
        private static DraftTeamSnapshot BestTeam(PitcherSnapshot p)=>Teams.OrderByDescending(x=>x.Need==TrainingFocus.Velocity?p.Stuff:x.Need==TrainingFocus.BreakingBall?p.Movement:x.Need==TrainingFocus.Stamina?p.Stamina:p.Command).ThenByDescending(x=>x.Demand).First();
        private static IReadOnlyList<MemoryCardId> MemoryOptions(HighSchoolCareerSnapshot s,ulong seed){var all=Enum.GetValues(typeof(MemoryCardId)).Cast<MemoryCardId>().ToList();var rng=new SplitMix64(seed^0x4D454D4F5259UL);for(var i=all.Count-1;i>0;i--){var j=rng.NextInt(i+1);var x=all[i];all[i]=all[j];all[j]=x;}return all.Take(Math.Max(s.MemorySlots,6)).ToArray();}
        private static PitcherSnapshot ApplyCreation(PitcherSnapshot p,CreationAllocationSnapshot a,PlayerIdentitySnapshot identity)=>new PitcherSnapshot(p.Id,identity.Name,Clamp(p.Stuff+a.Stuff,20,80),Clamp(p.Command+a.Command,20,80),Clamp(p.Movement+a.Movement,20,80),Clamp(p.Stamina+a.Stamina,20,80),p.PitchProfiles,identity.ThrowingHand);
        private static PitcherSnapshot ApplyKarmas(PitcherSnapshot p,IReadOnlyList<KarmaId> karmas){if(karmas.Contains(KarmaId.SingleWeapon))return new PitcherSnapshot(p.Id,p.Name,Clamp(p.Stuff+3,20,80),Clamp(p.Command-2,20,80),Clamp(p.Movement-2,20,80),p.Stamina,p.PitchProfiles,p.ThrowingHand);return p;}
        private static PitcherSnapshot ApplyInheritance(PitcherSnapshot p,int points,SoulDomain? domain,IReadOnlyList<MemoryCardId> memories,TalentSnapshot talent,int? version,int bonus){var rules=version==2?SoulInheritanceRulesVersion.V2:SoulInheritanceRulesVersion.V1;var remaining=AppliedInheritance(points,rules)+Math.Max(0,bonus);var value=p;var rotation=new[]{TrainingFocus.Velocity,TrainingFocus.Command,TrainingFocus.BreakingBall,TrainingFocus.Stamina};if(domain.HasValue&&remaining>0){var focus=domain==SoulDomain.Body?TrainingFocus.Velocity:domain==SoulDomain.Technique?TrainingFocus.Command:TrainingFocus.GamePlanning;var share=remaining/2;while(share-->0){value=Grow(value,focus,1);remaining--;}}while(remaining-->0){var focus=rotation.OrderBy(x=>Rating(x,value)).First();value=Grow(value,focus,1);}foreach(var memory in memories){if(memory==MemoryCardId.VelocityBlueprint)value=Tune(value,2,-1,0,0);else if(memory==MemoryCardId.FingertipMemory)value=Tune(value,0,0,2,-1);else if(memory==MemoryCardId.RecoveryRoutine)value=Tune(value,0,0,0,2);else value=Tune(value,0,1,1,0);}return value;}
        private static TalentSnapshot RaiseLowest(TalentSnapshot t){var abilities=Enum.GetValues(typeof(TalentAbility)).Cast<TalentAbility>().OrderBy(x=>t.Grade(x)).ToArray();var a=abilities[0];var next=t.Grade(a).Next();return next.HasValue?t.Replacing(a,next.Value,t.Pressure(a)):t;}
        private static PitcherSnapshot Grow(PitcherSnapshot p,TrainingFocus f,int points,int? balanceVersion=null,PitchType? targetPitch=null){if(points<=0)return p;if((balanceVersion??1)>=4)return PitcherGrowthRules.Grow(p,f,points,targetPitch);return new PitcherSnapshot(p.Id,p.Name,Clamp(p.Stuff+(f==TrainingFocus.Velocity?points:0),20,80),Clamp(p.Command+(f==TrainingFocus.Command||f==TrainingFocus.GamePlanning?points:0),20,80),Clamp(p.Movement+(f==TrainingFocus.BreakingBall?points:0),20,80),Clamp(p.Stamina+(f==TrainingFocus.Stamina||f==TrainingFocus.Recovery?points:0),20,80),p.PitchProfiles,p.ThrowingHand);}
        private static PitcherSnapshot Tune(PitcherSnapshot p,int stuff,int command,int movement,int stamina)=>new PitcherSnapshot(p.Id,p.Name,Clamp(p.Stuff+stuff,20,80),Clamp(p.Command+command,20,80),Clamp(p.Movement+movement,20,80),Clamp(p.Stamina+stamina,20,80),p.PitchProfiles,p.ThrowingHand);
        private static PitcherSnapshot ApplyAwakening(PitcherSnapshot p,AwakeningId a){var branch=AwakeningTree.GetBranch(a);return branch==AwakeningTree.Branch.Power?Tune(p,3,0,0,1):branch==AwakeningTree.Branch.Command?Tune(p,-1,4,0,0):branch==AwakeningTree.Branch.Breaking?Tune(p,0,-1,4,0):Tune(p,0,2,1,1);}
        private static int TrainingSignalBase(HighSchoolCareerSnapshot s,TrainingFocus f,TrainingIntensity i,bool hit){var basis=i==TrainingIntensity.Light?130:i==TrainingIntensity.Standard?210:280;return basis+(s.School!=null&&s.School.Strength==f?110:0)+(hit?90:0)-Math.Max(0,s.Fatigue-45)*3+Math.Max(0,16-(s.Schedule??CareerScheduleSnapshot.FixedDefault).TrainingTotal)*TrainingCompensationPerDeficit;}
        private static int TrainingGrowth(int signal)=>signal>=430?2:signal>=260?1:0;
        private static int TrainingArmRisk(TrainingFocus focus,TrainingIntensity intensity){if(intensity!=TrainingIntensity.Intensive)return 0;return focus==TrainingFocus.Velocity?3:focus==TrainingFocus.BreakingBall?2:focus==TrainingFocus.Stamina?1:0;}
        private static TrainingBlockStopReason? TrainingBlockStop(HighSchoolCareerSnapshot state,TrainingFocus focus)
        {
            if(state.Phase!=HighSchoolCareerPhase.Training)
            {
                if(state.Phase==HighSchoolCareerPhase.Relationship)return TrainingBlockStopReason.Relationship;
                if(state.Phase==HighSchoolCareerPhase.Awakening)return TrainingBlockStopReason.Awakening;
                if(state.Phase==HighSchoolCareerPhase.ImportantGame)return TrainingBlockStopReason.ImportantGame;
                return TrainingBlockStopReason.PhaseChanged;
            }
            if(state.LastTraining!=null&&state.LastTraining.BloomedAbility.HasValue)return TrainingBlockStopReason.TalentBloom;
            if(focus!=TrainingFocus.Recovery&&state.Fatigue>=75)return TrainingBlockStopReason.Fatigue;
            if(focus!=TrainingFocus.Recovery&&ArmHealthStateFor(state.ArmRisk,state.InjuryRecovery)!=ArmHealthState.Normal)return TrainingBlockStopReason.ArmHealth;
            return null;
        }
        private static int RatingTotal(PitcherSnapshot p)=>p.Stuff+p.Command+p.Movement+p.Stamina;
        private static int Rating(TrainingFocus f,PitcherSnapshot p)=>f==TrainingFocus.Velocity?p.Stuff:f==TrainingFocus.BreakingBall?p.Movement:f==TrainingFocus.Stamina||f==TrainingFocus.Recovery?p.Stamina:p.Command;
        private static string Label(TrainingFocus f)=>f==TrainingFocus.Velocity?"구위":f==TrainingFocus.Command?"제구":f==TrainingFocus.BreakingBall?"변화구":f==TrainingFocus.GamePlanning?"타자 상대법과 제구":"체력";
        private static string AwakeningTitle(AwakeningId a)=>a==AwakeningId.ExplosiveFastball?"폭발하는 포심":a==AwakeningId.PinpointEdge?"바늘끝 제구":a==AwakeningId.DisappearingBreaker?"사라지는 변화구":a.ToString();
        private static string OpportunityReason(TrainingFocus f)=>f==TrainingFocus.Velocity?"릴리스가 빨라졌습니다 — 오늘은 강한 공이 붙는 날입니다.":f==TrainingFocus.Command?"미트가 평소보다 크게 보입니다 — 코스를 다듬을 기회입니다.":f==TrainingFocus.BreakingBall?"손끝 감각이 선명합니다 — 변화구를 만질 날입니다.":f==TrainingFocus.Stamina?"하체가 가볍습니다 — 긴 이닝의 몸을 만들 기회입니다.":f==TrainingFocus.Recovery?"팔이 무겁다는 신호입니다 — 오늘은 회복이 최고의 훈련입니다.":"포수와 읽은 타자 습관이 남아 있습니다 — 경기 계획을 정리할 날입니다.";
        private sealed class Impact { public Impact(int trust,int fatigue,int fans,TrainingFocus? focus,string text){Trust=trust;Fatigue=fatigue;Fans=fans;Focus=focus;Text=text;}public int Trust;public int Fatigue;public int Fans;public TrainingFocus? Focus;public string Text; }
        private static Impact RelationshipImpact(string category,RelationshipResponse response){if(category=="rival")return response==RelationshipResponse.Challenge?new Impact(-1,2,7,TrainingFocus.BreakingBall,"다음 맞대결이 대회에서 가장 기대되는 승부가 됐습니다."):new Impact(3,0,1,TrainingFocus.GamePlanning,"상대가 읽은 반복 습관 하나를 알아냈습니다.");if(category=="health")return response==RelationshipResponse.Listen?new Impact(5,-6,0,null,"오늘은 공을 놓고 회복에 집중하기로 했습니다."):new Impact(-3,6,1,null,"쉬라는 말을 미루고 던졌지만 피로가 더 쌓였습니다.");if(category=="catcher")return response==RelationshipResponse.Listen?new Impact(4,0,0,null,"상대의 말을 끝까지 듣고 다음 준비 기준을 함께 확인했습니다."):response==RelationshipResponse.Explain?new Impact(8,0,0,TrainingFocus.GamePlanning,"두 사람이 본 근거를 합쳐 다음 경기의 구종 순서를 만들었습니다."):new Impact(-4,2,2,TrainingFocus.BreakingBall,"시험은 받아들였지만 포수의 불안은 남았습니다.");if(category=="coach")return response==RelationshipResponse.Listen?new Impact(4,0,0,null,"상대의 말을 끝까지 듣고 다음 준비 기준을 함께 확인했습니다."):response==RelationshipResponse.Explain?new Impact(7,0,0,TrainingFocus.Command,"몸 상태에 맞춰 훈련 강도를 다시 조정했습니다."):new Impact(-4,4,2,TrainingFocus.Velocity,"추가 테스트는 얻었지만 준비 과정을 설득하지 못했습니다.");return response==RelationshipResponse.Listen?new Impact(4,-2,1,null,"이번 일을 차분히 받아들였습니다."):response==RelationshipResponse.Explain?new Impact(3,0,2,TrainingFocus.GamePlanning,"선택의 이유를 기록으로 설명했습니다."):new Impact(1,3,3,TrainingFocus.Velocity,"결과로 답하기로 했습니다.");}
        private static string[] PrologueNews(PlayerIdentitySnapshot id,int life,int memories){if(life<2)return new[]{id.Region+" 중학교 마지막 대회에서 보여준 공이 같은 지역 네 고교의 관심을 끌었습니다."};var openers=new[]{id.Region+" 중학교 마지막 대회. 처음 서는 마운드인데 흙의 감촉이 낯설지 않았습니다. 같은 지역 네 고교가 다시 지켜보고 있습니다.",id.Region+" 중학교 마지막 대회에서 던진 마지막 공. 포수 미트에 꽂히는 소리가 어딘가 익숙했습니다. 네 고교의 시선이 모입니다.",id.Region+" 중학교 마지막 대회를 마친 뒤, 어깨보다 먼저 마음이 다음 이닝을 준비하고 있었습니다. 네 고교에서 제안이 도착했습니다."};return memories>0?new[]{openers[(life-2)%3],"처음 잡는 그립인데 손끝이 먼저 기억합니다 · 설명하기 어려운 감각 "+memories+"가지"}:new[]{openers[(life-2)%3]};}
        private static DraftTeamSnapshot T(string id,string name,TrainingFocus need,int demand,string plan,string competitor,string coach)=>new DraftTeamSnapshot(id,name,need,demand,plan,competitor,coach);
        private static HighSchoolCareerSnapshot Next(HighSchoolCareerSnapshot s){var n=s.Clone();n.Revision++;return n;}
        private static void Sign(HighSchoolCareerSnapshot s)
        {
            var ratings=s.Pitcher.Stuff+":"+s.Pitcher.Command+":"+s.Pitcher.Movement+":"+s.Pitcher.Stamina;
            var perf=s.Performance.ImportantGamesCompleted+":"+s.Performance.Pitches+":"+s.Performance.Strikeouts+":"+s.Performance.Walks+":"+s.Performance.RunsAllowed+":"+s.Performance.ExpectedDamage+":"+s.Performance.ActualDamage;
            var draft=s.DraftResult==null?"none":(s.DraftResult.Outcome==DraftOutcome.Drafted?"drafted":"undrafted")+":"+s.DraftResult.EvaluationScore+":"+(s.DraftResult.Team==null?"none":s.DraftResult.Team.Id);
            var canonical=new List<string>{
                s.CareerId,s.Revision.ToString(CultureInfo.InvariantCulture),s.Phase.Value(),
                s.Identity.Name,s.Identity.ThrowingHand==ThrowingHand.Right?"right":"left",BodyValue(s.Identity.BodyType),s.Identity.Region,
                s.School==null?"none":SchoolValue(s.School.Id),
                DifficultyValue(s.Difficulty.CareerHarshness),DifficultyValue(s.Difficulty.InformationClarity),DifficultyValue(s.Difficulty.SimulationDifficulty),AssistValue(s.Difficulty.InterventionAssist),
                string.Join(",",s.Karmas.Select(KarmaValue)),s.LegacyRewardPermille.ToString(),s.MemorySlots.ToString(),
                s.Chapter.Number.ToString(),s.ChapterTrainingCount.ToString(),s.TotalTrainingsCompleted.ToString(),s.MilestoneIndex.ToString(),s.RelationshipsCompleted.ToString(),s.RelationshipTrust.ToString(),
                string.Join(",",s.SelectedAwakenings.Select(x=>x.Value())),string.Join(",",s.AwakeningOptions.Select(x=>x.Value())),
                s.Fatigue.ToString(),ratings,perf,s.CurrentGameScenario==null?"none":s.CurrentGameScenario.Id,draft,
                string.Join(",",s.LegacyOptions.Select(x=>x.Value())),string.Join(",",s.SelectedMemories.Select(x=>x.Value()))
            };
            if(s.RivalTrust.HasValue)canonical.Add("relationships:"+(s.ManagerTrust??s.RelationshipTrust)+":"+(s.CatcherTrust??s.RelationshipTrust)+":"+(s.RivalTrust??s.RelationshipTrust));
            else if(s.ManagerTrust.HasValue||s.CatcherTrust.HasValue)canonical.Add("staff:"+(s.ManagerTrust??s.RelationshipTrust)+":"+(s.CatcherTrust??s.RelationshipTrust));
            if(s.BalanceVersion.HasValue)canonical.Add("balance_version:"+s.BalanceVersion.Value);
            if(s.WorldRulesVersion.HasValue)canonical.Add("world_rules_version:"+s.WorldRulesVersion.Value);
            if(s.ArmRisk.HasValue)canonical.Add("arm_risk:"+s.ArmRisk.Value);
            if(s.InjuryRecovery.HasValue)canonical.Add("injury_recovery:"+s.InjuryRecovery.Value);
            if(s.AwakeningSparks.HasValue)canonical.Add("awakening_sparks:"+s.AwakeningSparks.Value);
            if(s.SoulBoosts!=null&&s.SoulBoosts.Count>0)canonical.Add("soul_boosts:"+string.Join(",",s.SoulBoosts));
            if(s.Schedule!=null)canonical.Add("schedule:"+s.Schedule.CommitmentToken);
            if(s.LastRelationship!=null){var r=s.LastRelationship;canonical.Add(string.Join(":",new[]{"last_relationship",r.Number.ToString(),r.Category,r.Title,r.Response==RelationshipResponse.Listen?"listen":r.Response==RelationshipResponse.Explain?"explain":"challenge",r.TrustBefore.ToString(),r.TrustAfter.ToString(),r.FatigueBefore.ToString(),r.FatigueAfter.ToString(),r.FanInterestBefore.ToString(),r.FanInterestAfter.ToString(),r.GrowthFocus.HasValue?r.GrowthFocus.Value.Value():"none",r.AbilityBefore.HasValue?r.AbilityBefore.Value.ToString():"none",r.AbilityAfter.HasValue?r.AbilityAfter.Value.ToString():"none",r.Feedback,"current_fan_interest",s.FanInterest.ToString()}));}
            s.StateCommitment=StableHash.Fnv1A64(string.Join("|",canonical));
        }
        private static string BodyValue(BodyType value)=>value==BodyType.Compact?"compact":value==BodyType.Tall?"tall":"balanced";
        private static string DifficultyValue(DifficultyLevel value)=>value==DifficultyLevel.Relaxed?"relaxed":value==DifficultyLevel.Challenging?"challenging":"standard";
        private static string AssistValue(InterventionAssist value)=>value==InterventionAssist.Full?"full":value==InterventionAssist.Minimal?"minimal":"standard";
        private static string SchoolValue(SchoolId value)=>value==SchoolId.HanbitTraditional?"hanbit_traditional":value==SchoolId.MiraeAnalytics?"mirae_analytics":value==SchoolId.HaedongPower?"haedong_power":"cheongam_development";
        private static string KarmaValue(KarmaId value){switch(value){case KarmaId.UnknownLand:return "unknown_land";case KarmaId.StubbornCoach:return "stubborn_coach";case KarmaId.SingleWeapon:return "single_weapon";case KarmaId.GeniusGeneration:return "genius_generation";case KarmaId.ErasedMemory:return "erased_memory";default:return "no_last_chance";}}
        private static HighSchoolCareerResult Finish(ulong seed,HighSchoolCareerSnapshot s,string evt,IReadOnlyList<string> reasons=null){Sign(s);return Result(seed,s,evt,reasons);}
        private static HighSchoolCareerResult Result(ulong seed,HighSchoolCareerSnapshot s,string evt,IReadOnlyList<string> reasons=null){var rng=new SplitMix64(seed^s.Revision^0x4556454E5400UL);var next=rng.Next().ToString(CultureInfo.InvariantCulture);var events=new[]{new HighSchoolCareerEvent(evt,0,reasons)};var hash=StableHash.Fnv1A64(s.CareerId+"|"+s.Revision+"|"+evt+"|"+next+"|"+s.StateCommitment);return new HighSchoolCareerResult(s.Revision,next,events,s,hash);}
        private static ulong Validate(string seed,HighSchoolCareerSnapshot s,HighSchoolCareerPhase phase){var value=Seed(seed);if(s==null||s.Phase!=phase||string.IsNullOrEmpty(s.StateCommitment))throw Invalid("career state or phase is invalid");var copy=s.Clone();Sign(copy);if(copy.StateCommitment!=s.StateCommitment)throw Invalid("career state or phase is invalid");return value;}
        private static ulong Seed(string text){ulong value;if(!ulong.TryParse(text,NumberStyles.None,CultureInfo.InvariantCulture,out value))throw new SimulationException(SimulationErrorCode.InvalidSeed,"invalid seed: "+text);return value;}
        private static SimulationException Invalid(string text)=>new SimulationException(SimulationErrorCode.InvalidGameState,text);
        private static RivalSnapshot MakeRival(ulong seed,DifficultyLevel level,IReadOnlyList<KarmaId> karmas,int wind){var rng=new SplitMix64(seed^0x524956414C00UL);var b=Rivals[rng.NextInt(Rivals.Length)];var bonus=(level==DifficultyLevel.Relaxed?-3:level==DifficultyLevel.Challenging?4:0)+(karmas.Contains(KarmaId.GeniusGeneration)?4:0)+wind;return new RivalSnapshot(b.Id,b.Name,b.Archetype,Clamp(b.Contact+bonus,20,80),Clamp(b.Discipline+bonus,20,80),Clamp(b.Power+bonus,20,80),b.Personality,b.SignatureRecord);}
        private static int Clamp(int value,int min,int max)=>Math.Min(max,Math.Max(min,value));
    }
    internal static class HighSchoolListExtensions { public static int IndexOf<T>(this IReadOnlyList<T> values,T item){for(var i=0;i<values.Count;i++)if(EqualityComparer<T>.Default.Equals(values[i],item))return i;return -1;} }
